-- Explicações por artigo — Código de Processo Penal. Texto-base: dispositivos oficiais já cadastrados em legal_course_units.

-- Entram como 'under_review': só administradores veem até a publicação (update ... set status = 'published').

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O Código de Processo Penal vale em todo o território brasileiro. Há ressalvas: tratados, convenções e regras de direito internacional; prerrogativas constitucionais do Presidente da República, dos ministros de Estado e dos ministros do Supremo Tribunal Federal nos crimes de responsabilidade; processos da Justiça Militar; processos do tribunal especial; e crimes de imprensa. Aos dois últimos, o Código se aplica quando as leis especiais não dispuserem de modo diverso.', '["Regra: o CPP rege o processo penal em todo o território brasileiro.","Ressalvas: tratados e regras internacionais; prerrogativas constitucionais; Justiça Militar; tribunal especial; crimes de imprensa.","Parágrafo único: aplica-se aos processos do tribunal especial e de imprensa, se a lei especial não dispuser diferente."]'::jsonb, '["O texto remete a normas de constituição anterior: é leitura histórica.","Há referência à ADPF nº 130 no texto compilado (crimes de imprensa)."]'::jsonb, 'Um processo da competência da Justiça Militar segue a legislação militar, e não o CPP.', '["Assertiva que aplica o CPP a processos da Justiça Militar erra: ela é ressalvada."]'::jsonb, '[]'::jsonb, '["Art. 2º","Art. 3º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-1'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A lei processual penal aplica-se desde logo (aplicação imediata), sem prejuízo da validade dos atos realizados sob a vigência da lei anterior (princípio do tempus regit actum).', '["Aplicação imediata da lei processual penal.","Os atos já praticados sob a lei anterior continuam válidos."]'::jsonb, '["Normas processuais penais materiais (mistas) seguem a lei penal: retroatividade benéfica."]'::jsonb, 'Nova regra de intimação vale para os atos futuros; as intimações já feitas continuam válidas.', '["Assertiva que invalida os atos realizados sob a lei anterior, por força da nova lei processual, erra: eles permanecem válidos."]'::jsonb, '[{"termo":"Tempus regit actum","significado":"O ato se rege pela lei vigente quando praticado."}]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-2'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A lei processual penal admite interpretação extensiva e aplicação analógica, bem como o suplemento dos princípios gerais de direito.', '["Interpretação extensiva é admitida.","Aplicação analógica é admitida.","Princípios gerais de direito suplementam a lei."]'::jsonb, '["Diferente do direito penal material, a analogia em prejuízo do réu é debatida: a doutrina distingue normas processuais das de caráter material."]'::jsonb, 'Aplicar por analogia regra processual civil a lacuna do CPP.', '["Assertiva que veda interpretação extensiva e analogia na lei processual penal erra: ambas são admitidas."]'::jsonb, '[{"termo":"Interpretação extensiva","significado":"Amplia o alcance literal da norma para o que o legislador quis dizer."}]'::jsonb, '["Art. 1º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-3'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O processo penal terá estrutura acusatória, vedadas a iniciativa do juiz na fase de investigação e a substituição da atuação probatória do órgão de acusação. O texto compilado indica discussão de sua eficácia no Supremo Tribunal Federal (ADIs).', '["Estrutura acusatória do processo penal.","Veda a iniciativa do juiz na fase de investigação.","Veda a substituição da atuação probatória do órgão de acusação."]'::jsonb, '["Dispositivo incluído pela Lei nº 13.964, de 2019 (Pacote Anticrime).","Eficácia discutida em ADIs: confira a situação atual."]'::jsonb, 'O juiz não pode determinar, por conta própria, a produção de prova em substituição ao Ministério Público.', '["Assertiva que permite ao juiz a iniciativa na fase de investigação, segundo o art. 3º-A, erra."]'::jsonb, '[{"termo":"Sistema acusatório","significado":"Separação entre quem acusa, quem defende e quem julga."}]'::jsonb, '["Art. 3º-B","Art. 156"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-3-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz das garantias é responsável pelo controle da legalidade da investigação criminal e pela salvaguarda dos direitos individuais cuja franquia tenha sido reservada à autorização prévia do Poder Judiciário. Entre outras funções, recebe a comunicação imediata da prisão e o auto de prisão em flagrante, zela pelos direitos do preso, decide sobre prisão provisória e medidas cautelares, e decide sobre a homologação de acordo de não persecução penal ou de colaboração premiada formalizados durante a investigação. O preso será encaminhado à audiência de custódia no prazo de 24 horas. Se o investigado estiver preso, o juiz das garantias pode prorrogar o inquérito, uma única vez, por até 15 dias, após o que a prisão será relaxada.', '["Controla a legalidade da investigação e protege direitos individuais sob reserva de jurisdição.","Recebe a comunicação da prisão e o auto de flagrante.","Decide sobre prisão provisória e outras cautelares.","Homologa ANPP e colaboração premiada na fase de investigação.","§1º: audiência de custódia em 24 horas, por videoconferência.","§2º: prorrogação única do inquérito do preso, por até 15 dias; depois, relaxamento."]'::jsonb, '["Eficácia do instituto discutida em ADIs: confira a situação atual.","A redação do §1º veio da Lei nº 15.358, de 2026."]'::jsonb, 'O juiz das garantias decide sobre pedido de interceptação durante o inquérito.', '["Assertiva que atribui ao juiz das garantias o julgamento do mérito da ação penal erra: sua função é a legalidade da investigação."]'::jsonb, '[]'::jsonb, '["Art. 3º-C","Art. 310"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-3-b'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A competência do juiz das garantias abrange todas as infrações penais, exceto as de menor potencial ofensivo, e cessa com o recebimento da denúncia ou queixa. Recebida a denúncia, as questões pendentes serão decididas pelo juiz da instrução e julgamento. As decisões do juiz das garantias não vinculam o juiz da instrução e julgamento, que, após o recebimento da denúncia ou queixa, deverá reexaminar a necessidade das medidas cautelares em curso, no prazo máximo de 10 dias. Os autos das matérias do juiz das garantias ficam acautelados na secretaria desse juízo, à disposição do Ministério Público e da defesa, e não são apensados ao processo, ressalvados os documentos relativos às provas irrepetíveis, medidas de obtenção de provas ou de antecipação de provas. Fica assegurado às partes o amplo acesso aos autos acautelados.', '["Abrange todas as infrações, exceto as de menor potencial ofensivo.","Cessa com o recebimento da denúncia ou queixa.","Juiz da instrução reexamina as cautelares em até 10 dias.","Autos do juízo das garantias ficam na secretaria, com acesso amplo às partes.","Exceção ao não apensamento: provas irrepetíveis, medidas de obtenção e antecipação de provas."]'::jsonb, '["Eficácia discutida em ADIs.","Prazo de 10 dias para reexame das cautelares."]'::jsonb, 'Após o recebimento da denúncia, outro juiz assume o processo e reexamina a prisão preventiva em até 10 dias.', '["Assertiva que estende a competência do juiz das garantias às infrações de menor potencial ofensivo erra: elas são excluídas."]'::jsonb, '[]'::jsonb, '["Art. 3º-B","Art. 399"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-3-c'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz que, na fase de investigação, praticar qualquer ato incluído nas competências dos arts. 4º e 5º do Código ficará impedido de funcionar no processo. Nas comarcas em que funcionar apenas um juiz, os tribunais criarão um sistema de rodízio de magistrados.', '["Juiz que atua na investigação fica impedido de funcionar no processo.","Comarca com um só juiz: rodízio de magistrados criado pelos tribunais."]'::jsonb, '["Eficácia discutida em ADIs."]'::jsonb, 'O juiz que decretou medida cautelar na investigação não julga o processo.', '["Assertiva que permite ao juiz da investigação julgar o processo, segundo o art. 3º-D, erra."]'::jsonb, '[]'::jsonb, '["Art. 3º-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-3-d'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz das garantias será designado conforme as normas de organização judiciária da União, dos Estados e do Distrito Federal, observando critérios objetivos a serem periodicamente divulgados pelo respectivo tribunal.', '["Designação conforme a organização judiciária.","Critérios objetivos, periodicamente divulgados pelo tribunal."]'::jsonb, '["Eficácia discutida em ADIs."]'::jsonb, 'O tribunal divulga os critérios objetivos para designar o juiz das garantias.', '["Assertiva que dispensa critérios objetivos na designação do juiz das garantias erra."]'::jsonb, '[]'::jsonb, '["Art. 3º-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-3-e'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'O juiz das garantias deve assegurar o cumprimento das regras para o tratamento dos presos, impedindo o acordo ou ajuste de qualquer autoridade com órgãos da imprensa para explorar a imagem da pessoa submetida à prisão, sob pena de responsabilidade civil, administrativa e penal. Por regulamento, as autoridades disciplinarão, em 180 dias, o modo padronizado de transmitir à imprensa as informações sobre a prisão e a identidade do preso.', '["Garantir as regras de tratamento dos presos.","Impedir acordo com a imprensa para explorar a imagem do preso.","Responsabilidade civil, administrativa e penal.","Parágrafo único: regulamento em 180 dias para padronizar as informações à imprensa."]'::jsonb, '["Eficácia discutida em ADIs."]'::jsonb, 'Autoridade combina com a imprensa a exposição da imagem do preso: pode ser responsabilizada.', '["Assertiva que permite a exploração da imagem do preso mediante acordo com a imprensa erra."]'::jsonb, '[]'::jsonb, '["Art. 3º-B"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-3-f'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A polícia judiciária será exercida pelas autoridades policiais no território de suas respectivas circunscrições e terá por fim a apuração das infrações penais e da sua autoria. A competência não exclui a de autoridades administrativas a quem a lei atribua a mesma função.', '["Polícia judiciária exercida por autoridades policiais nas suas circunscrições.","Finalidade: apurar infrações penais e autoria.","Parágrafo único: não exclui outras autoridades administrativas com a mesma função."]'::jsonb, '["Exemplo clássico: Comissões Parlamentares de Inquérito têm poderes de investigação próprios."]'::jsonb, 'O delegado de polícia apura o crime na sua circunscrição.', '["Assertiva que torna a polícia judiciária exclusiva das autoridades policiais erra: o parágrafo único admite outras autoridades."]'::jsonb, '[{"termo":"Polícia judiciária","significado":"Apura infrações penais e autoria, auxiliando o Judiciário e o Ministério Público."}]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-4'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes de ação pública, o inquérito policial é iniciado de ofício ou mediante requisição da autoridade judiciária ou do Ministério Público, ou a requerimento do ofendido ou de quem tiver qualidade para representá-lo. O requerimento conterá, sempre que possível, a narração do fato com as circunstâncias; a individualização do indiciado e as razões de convicção; e a nomeação das testemunhas. Do despacho que indeferir o requerimento cabe recurso para o chefe de Polícia. Qualquer pessoa do povo pode comunicar a infração à autoridade (delatio criminis). Nos crimes de ação pública condicionada à representação, o inquérito não pode ser iniciado sem ela. Nos crimes de ação privada, a autoridade só procede a inquérito a requerimento de quem tenha qualidade para intentar a ação.', '["Ação pública: inquérito de ofício, por requisição ou a requerimento do ofendido.","§1º: conteúdo do requerimento (fato, indiciado, testemunhas).","§2º: recurso ao chefe de Polícia contra o indeferimento.","§3º: qualquer pessoa pode comunicar o fato.","§4º: representação é condição para iniciar o inquérito.","§5º: ação privada: só a requerimento do legitimado."]'::jsonb, '["Requisição do Ministério Público ou do juiz não pode ser recusada sem fundamento.","Sem representação, não há inquérito na ação pública condicionada."]'::jsonb, 'Vítima de crime de ação pública condicionada precisa representar para que o inquérito se instaure.', '["Assertiva que permite instaurar inquérito em ação pública condicionada sem representação erra: o §4º veda."]'::jsonb, '[{"termo":"Delatio criminis","significado":"Comunicação de crime à autoridade."}]'::jsonb, '["Art. 24","Art. 39"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-5'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Logo que tiver conhecimento da prática da infração penal, a autoridade policial deve: dirigir-se ao local e preservá-lo até a chegada dos peritos; apreender os objetos relacionados ao fato, após liberados pelos peritos; colher todas as provas; ouvir o ofendido; ouvir o indiciado; proceder a reconhecimento de pessoas e coisas e a acareações; determinar exame de corpo de delito e outras perícias; ordenar a identificação datiloscópica e juntar a folha de antecedentes; averiguar a vida pregressa do indiciado; e colher informações sobre a existência de filhos, idades, eventual deficiência e o responsável pelos cuidados indicado pela pessoa presa.', '["Preservar o local do crime até a chegada dos peritos.","Apreender objetos após liberados pelos peritos.","Colher provas, ouvir ofendido e indiciado.","Reconhecimento de pessoas e coisas, acareações.","Exame de corpo de delito e perícias.","Identificação datiloscópica e folha de antecedentes.","Vida pregressa do indiciado.","Informações sobre filhos da pessoa presa."]'::jsonb, '["O termo do interrogatório do indiciado é assinado por duas testemunhas que ouviram a leitura.","O inciso X (filhos) veio da Lei nº 13.257, de 2016."]'::jsonb, 'Ao chegar ao local do crime, o delegado providencia que nada seja alterado até a perícia.', '["Assertiva que autoriza a apreensão de objetos antes de liberados pelos peritos erra."]'::jsonb, '[]'::jsonb, '["Art. 5º","Art. 158"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-6'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Para verificar a possibilidade de a infração ter sido praticada de determinado modo, a autoridade policial pode proceder à reprodução simulada dos fatos (reconstituição), desde que esta não contrarie a moralidade ou a ordem pública.', '["Reprodução simulada dos fatos (reconstituição).","Limite: não contrariar a moralidade ou a ordem pública."]'::jsonb, '["O investigado não pode ser obrigado a participar (direito de não produzir prova contra si)."]'::jsonb, 'Reconstituição do crime no local, com a participação voluntária do investigado.', '["Assertiva que obriga o investigado a participar da reconstituição erra."]'::jsonb, '[]'::jsonb, '["Art. 6º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-7'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Havendo prisão em flagrante, será observado o disposto no Capítulo II do Título IX deste Livro.', '["Prisão em flagrante segue o Capítulo II do Título IX do Livro I."]'::jsonb, '["Remissão às regras do flagrante (arts. 301 e seguintes)."]'::jsonb, 'Preso em flagrante, o indivíduo é conduzido à autoridade e o auto é lavrado.', '["Assertiva que cria rito próprio no art. 8º para o flagrante erra: ele remete ao Título da prisão."]'::jsonb, '[]'::jsonb, '["Art. 301"]'::jsonb, 'under_review', 'claude'
