insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A autoridade assegurará no inquérito o sigilo necessário à elucidação do fato ou exigido pelo interesse da sociedade. Nos atestados de antecedentes solicitados, a autoridade policial não pode mencionar anotações referentes à instauração de inquérito contra os requerentes.', '["Sigilo do inquérito, quando necessário à elucidação ou ao interesse da sociedade.","Atestados de antecedentes não mencionam a instauração de inquérito."]'::jsonb, '["O sigilo não alcança o advogado (Súmula Vinculante 14), quanto às provas já documentadas."]'::jsonb, 'Atestado de antecedentes não pode informar que há inquérito em curso contra o requerente.', '["Assertiva que oponibiliza o sigilo do inquérito ao advogado em relação a provas já documentadas erra."]'::jsonb, '[]'::jsonb, '["Art. 7º do Estatuto da Advocacia"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-20'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A incomunicabilidade do indiciado depende de despacho nos autos e somente será permitida quando o interesse da sociedade ou a conveniência da investigação o exigir. A incomunicabilidade, que não excederá três dias, será decretada por despacho fundamentado do juiz, a requerimento da autoridade policial ou do Ministério Público, respeitado o Estatuto da Ordem dos Advogados.', '["Incomunicabilidade depende de despacho nos autos.","Prazo máximo de três dias.","Decretada por despacho fundamentado do juiz.","Respeita a prerrogativa do advogado."]'::jsonb, '["Entende-se majoritariamente que o dispositivo não foi recepcionado pela Constituição vigente."]'::jsonb, 'Dispositivo hoje tem pouca aplicação prática.', '["Assertiva que permite incomunicabilidade por prazo indeterminado erra: o texto fixa limite de três dias."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-21'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'No Distrito Federal e nas comarcas com mais de uma circunscrição policial, a autoridade com exercício em uma delas pode, nos inquéritos que presidir, ordenar diligências em circunscrição de outra, independentemente de precatórias ou requisições, e providenciará, até que compareça a autoridade competente, sobre qualquer fato que ocorra em sua presença noutra circunscrição.', '["Diligências em outra circunscrição da mesma comarca, sem precatória.","Providências urgentes em outra circunscrição até a chegada da autoridade competente."]'::jsonb, '["Aplica-se ao Distrito Federal e às comarcas com mais de uma circunscrição policial."]'::jsonb, 'Delegado de uma delegacia da comarca realiza diligência na área de outra, sem precisar de precatória.', '["Assertiva que exige precatória para diligências em circunscrições da mesma comarca erra."]'::jsonb, '[]'::jsonb, '["Art. 4º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-22'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao remeter os autos do inquérito ao juiz competente, a autoridade policial oficiará ao Instituto de Identificação e Estatística, ou repartição congênere, mencionando o juízo a que forem distribuídos e os dados relativos à infração penal e ao indiciado.', '["Na remessa ao juiz, a polícia oficia o Instituto de Identificação e Estatística.","Informa o juízo, a infração e o indiciado."]'::jsonb, '["Finalidade: manter atualizados os registros e estatísticas criminais."]'::jsonb, 'Ao encaminhar o inquérito, o delegado comunica ao instituto de identificação o juízo de distribuição.', '["Assertiva que dispensa a comunicação ao Instituto de Identificação erra."]'::jsonb, '[]'::jsonb, '["Art. 10"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-23'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Nos crimes de ação pública, a ação é promovida por denúncia do Ministério Público, mas dependerá, quando a lei o exigir, de requisição do Ministro da Justiça ou de representação do ofendido ou de quem tiver qualidade para representá-lo. No caso de morte do ofendido ou quando declarado ausente por decisão judicial, o direito de representação passa ao cônjuge, ascendente, descendente ou irmão. Qualquer que seja o crime, quando praticado em detrimento do patrimônio ou interesse da União, Estado e Município, a ação penal será pública.', '["Ação pública: denúncia do Ministério Público.","Pode depender de requisição do Ministro da Justiça ou representação do ofendido.","§1º: morte ou ausência do ofendido: representação passa ao cônjuge, ascendente, descendente ou irmão.","§2º: crime contra patrimônio ou interesse da União, Estado e Município: ação pública."]'::jsonb, '["Ordem de sucessão: cônjuge, ascendente, descendente, irmão (CADI)."]'::jsonb, 'Morte do ofendido: o cônjuge pode oferecer a representação.', '["Assertiva que torna privada a ação penal de crime contra o patrimônio da União erra: será pública."]'::jsonb, '[{"termo":"Representação","significado":"Autorização da vítima para o Ministério Público agir."}]'::jsonb, '["Art. 25","Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-24'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A representação do ofendido será irretratável depois de oferecida a denúncia: até esse momento, ele ainda pode se arrepender e retratar-se.', '["Representação pode ser retratada até o oferecimento da denúncia.","Oferecida a denúncia, é irretratável."]'::jsonb, '["Marco: OFERECIMENTO da denúncia (não o recebimento)."]'::jsonb, 'A vítima se arrepende após a denúncia: não pode retratar a representação.', '["Assertiva que fixa o recebimento da denúncia como marco da irretratabilidade erra: é o oferecimento."]'::jsonb, '[]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-25'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'A ação penal, nas contravenções, será iniciada com o auto de prisão em flagrante ou por meio de portaria expedida pela autoridade judiciária ou policial.', '["Contravenções: início pelo auto de prisão em flagrante ou por portaria."]'::jsonb, '["Dispositivo não recepcionado pela Constituição vigente (privatividade da ação penal pública do Ministério Público)."]'::jsonb, 'Dispositivo hoje sem aplicação, pois a ação pública é privativa do Ministério Público.', '["Assertiva que admite portaria da autoridade policial para iniciar a ação penal hoje erra."]'::jsonb, '[{"termo":"Processo judicialiforme","significado":"Ação iniciada de ofício por portaria ou auto de prisão."}]'::jsonb, '["Art. 24"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-26'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Qualquer pessoa do povo pode provocar a iniciativa do Ministério Público, nos casos em que caiba a ação pública, fornecendo-lhe, por escrito, informações sobre o fato e a autoria e indicando o tempo, o lugar e os elementos de convicção.', '["Qualquer pessoa pode provocar o Ministério Público.","Por escrito, informando fato, autoria, tempo, lugar e elementos de convicção."]'::jsonb, '["A provocação não vincula o Ministério Público."]'::jsonb, 'Cidadão envia ao MP, por escrito, informações sobre um crime de ação pública.', '["Assertiva que obriga o MP a denunciar após a provocação de qualquer pessoa erra."]'::jsonb, '[]'::jsonb, '["Art. 5º"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-27'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ordenado o arquivamento do inquérito policial ou de elementos informativos de mesma natureza, o órgão do Ministério Público comunicará à vítima, ao investigado e à autoridade policial e encaminhará os autos para a instância de revisão ministerial para homologação. Se a vítima ou seu representante legal não concordar, poderá, no prazo de 30 dias do recebimento da comunicação, submeter a matéria à revisão da instância competente do órgão ministerial. Nas ações relativas a crimes em detrimento da União, Estados e Municípios, a revisão pode ser provocada pela chefia do órgão a quem couber a representação judicial.', '["O MP ordena o arquivamento e comunica vítima, investigado e polícia.","Autos seguem à instância de revisão ministerial para homologação.","Vítima discordante: 30 dias para submeter à revisão.","Crimes contra entes públicos: revisão pode ser provocada pela chefia do órgão de representação judicial."]'::jsonb, '["Eficácia discutida em ADIs.","O arquivamento deixou de ser homologado pelo juiz."]'::jsonb, 'Vítima discorda do arquivamento e, em 30 dias, pede revisão ao órgão superior do MP.', '["Assertiva que mantém a homologação do arquivamento pelo juiz, nos termos do art. 28, erra: ela é feita pela instância de revisão ministerial."]'::jsonb, '[]'::jsonb, '["Art. 17","Art. 18"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-28'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Não sendo caso de arquivamento e tendo o investigado confessado formal e circunstancialmente a prática de infração penal sem violência ou grave ameaça e com pena mínima inferior a 4 anos, o Ministério Público pode propor acordo de não persecução penal, desde que necessário e suficiente para reprovação e prevenção do crime, mediante condições ajustadas cumulativa e alternativamente: reparar o dano ou restituir a coisa; renunciar a bens e direitos instrumentos, produto ou proveito do crime; prestar serviço à comunidade; pagar prestação pecuniária; ou cumprir outra condição indicada pelo Ministério Público. A vítima é intimada da homologação do acordo e de seu descumprimento. Descumpridas as condições, o MP comunica o juízo para rescisão e oferece a denúncia; o descumprimento pode também justificar o não oferecimento de suspensão condicional do processo. A celebração e o cumprimento do acordo não constam de certidão de antecedentes, salvo para os fins do inciso III do §2º. Cumprido integralmente, o juízo decreta a extinção de punibilidade. Em caso de recusa do MP em propor o acordo, o investigado pode requerer a remessa dos autos a órgão superior, na forma do art. 28.', '["Requisitos: confissão formal e circunstanciada; infração sem violência ou grave ameaça; pena mínima inferior a 4 anos.","Acordo necessário e suficiente para reprovação e prevenção do crime.","Condições: reparar o dano, renunciar a bens, prestar serviço, pagar prestação pecuniária, outra condição.","A vítima é intimada da homologação e do descumprimento.","Descumprimento: rescisão e denúncia; pode impedir a suspensão condicional do processo.","Cumprimento integral: extinção de punibilidade.","Recusa do MP: remessa a órgão superior (art. 28)."]'::jsonb, '["O limite é a pena MÍNIMA inferior a 4 anos.","Eficácia discutida em ADIs.","Cumprido o acordo, não constam antecedentes (salvo exceção)."]'::jsonb, 'Investigado confesso de furto sem violência, com pena mínima baixa, aceita acordo e repara o dano.', '["Assertiva que exige pena máxima inferior a 4 anos para o ANPP erra: o critério é a pena mínima."]'::jsonb, '[{"termo":"ANPP","significado":"Acordo de não persecução penal."}]'::jsonb, '["Art. 28","Art. 395"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-28-a'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Será admitida ação privada nos crimes de ação pública se esta não for intentada no prazo legal. Cabe ao Ministério Público aditar a queixa, repudiá-la e oferecer denúncia substitutiva, intervir em todos os termos do processo, fornecer elementos de prova, interpor recurso e, a todo tempo, no caso de negligência do querelante, retomar a ação como parte principal.', '["Ação privada subsidiária da pública, se a denúncia não for oferecida no prazo legal.","MP pode aditar a queixa, repudiá-la e oferecer denúncia substitutiva.","MP intervém em todos os termos, fornece prova e recorre.","Em caso de negligência do querelante, o MP retoma a ação como parte principal."]'::jsonb, '["Exige INÉRCIA do Ministério Público. Pedido de arquivamento ou requisição de diligências não autoriza a ação subsidiária."]'::jsonb, 'O MP não oferece denúncia no prazo legal, e a vítima ajuíza queixa subsidiária.', '["Assertiva que permite a ação subsidiária mesmo quando o MP pede o arquivamento erra."]'::jsonb, '[{"termo":"Querelante","significado":"Quem ajuíza a queixa-crime."}]'::jsonb, '["Art. 5º, LIX da Constituição"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-29'
on conflict (unit_id) do update set content_sha256 = excluded.content_sha256, simples = excluded.simples, pontos = excluded.pontos, atencao = excluded.atencao, exemplo = excluded.exemplo, prova = excluded.prova, termos = excluded.termos, remissoes = excluded.remissoes, status = case when public.legal_unit_explanations.status = 'published' then 'published' else 'under_review' end, updated_at = now();

insert into public.legal_unit_explanations (unit_id, content_sha256, simples, pontos, atencao, exemplo, prova, termos, remissoes, status, authored_by)
select u.id, u.content_sha256, 'Ao ofendido ou a quem tenha qualidade para representá-lo caberá intentar a ação privada.', '["Legitimado a propor a ação privada: o ofendido ou quem o represente."]'::jsonb, '["Para pessoa menor ou incapaz, a legitimidade passa ao representante legal."]'::jsonb, 'Vítima de calúnia ajuíza queixa-crime contra o ofensor.', '["Assertiva que atribui ao Ministério Público a propositura da ação privada erra: cabe ao ofendido ou seu representante."]'::jsonb, '[]'::jsonb, '["Art. 31"]'::jsonb, 'under_review', 'claude'
from public.legal_course_units u join public.legal_courses c on c.id = u.course_id where c.slug = 'codigo-processo-penal' and u.unit_key = 'art-30'
